    26	export const EmailForm = ({ emailValue, onEmailChange, onSubmit, isLoading = false, inputRef }: EmailFormProps) => {
    27	  const { t } = useUiCopy();
    28	  const emailLabel = t('login.drawer.email', 'Email');
    29	  const sendCode = t('login.drawer.sendCode', 'Send code');
    30	  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});
    31	  const [validationError, setValidationError] = useState<string | undefined>();
    32	
    33	  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    34	    e.preventDefault();
    35	    // `disabled={isLoading}` on the submit button only blocks a click — pressing Enter in the
    36	    // email input still submits the form while a request is already in flight.
    37	    if (isLoading) return;
    38	    const trimmed = emailValue.trim();
    39	    if (!trimmed) {
    40	      setValidationError(VALIDATION_EMPTY);
    41	      return;
    42	    }
    43	    if (!EMAIL_RE.test(trimmed)) {
    44	      setValidationError(VALIDATION_EMAIL);
    45	      return;
    46	    }
    47	    setValidationError(undefined);
    48	    const result = await onSubmit();
    49	    if (result && !result.success && result.error) {
    50	      setValidationError(result.error);
    51	    }
    52	  };
